"""Deterministic zero-API-cost digital product factory. Run: python factory/build.py"""
from pathlib import Path
import csv, json, html, zipfile, datetime
ROOT=Path(__file__).resolve().parents[1]
SITE=ROOT/'site'; PRODUCTS=ROOT/'products'; SITE.mkdir(exist_ok=True); PRODUCTS.mkdir(exist_ok=True)
CATALOG=[
 {'slug':'freelance-rate-calculator','title':'Freelance Rate Calculator','category':'Business','desc':'Estimate a sustainable hourly rate using expenses, tax reserve, target earnings and billable hours.','price':'Free','kind':'calculator'},
 {'slug':'small-business-cashflow','title':'Small Business Cashflow Kit','category':'Finance','desc':'A 12-month editable cashflow CSV and practical instructions.','price':'Free','kind':'csv'},
 {'slug':'project-quote-template','title':'Project Quotation Kit','category':'Operations','desc':'Editable quote spreadsheet with quantities, rates, VAT and totals.','price':'Free','kind':'csv'},
]
CSS='''*{box-sizing:border-box}body{margin:0;font:16px/1.6 system-ui,-apple-system,Segoe UI,sans-serif;background:#0c1220;color:#f4f6fb}a{color:inherit}.wrap{max-width:1060px;margin:auto;padding:24px}header{border-bottom:1px solid #263246}header .wrap{display:flex;justify-content:space-between;align-items:center}header a{text-decoration:none}.brand{font-weight:800;letter-spacing:.02em}.pill{border:1px solid #455269;padding:5px 12px;border-radius:99px;font-size:12px;color:#cbd5e1}.hero{padding:74px 0 48px}h1{font-size:clamp(34px,6vw,64px);line-height:1.1;max-width:780px;margin:0 0 20px}h2{font-size:28px}.muted{color:#afbbcc}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:18px}.card{background:#151f30;border:1px solid #2c3b50;border-radius:16px;padding:24px}.card h3{margin:8px 0}.tag{font-size:12px;text-transform:uppercase;letter-spacing:.1em;color:#7de7b1}.btn{display:inline-block;background:#9ff3c8;color:#071a13;font-weight:750;border:0;border-radius:9px;padding:11px 17px;text-decoration:none;cursor:pointer}.btn:hover{background:#c4ffdf}footer{border-top:1px solid #263246;margin-top:80px;padding:20px 0;color:#afbbcc;font-size:13px}input{width:100%;padding:10px;background:#0b1321;border:1px solid #44546b;border-radius:8px;color:white;font:inherit}label{display:block;margin:12px 0}strong.result{font-size:30px;color:#9ff3c8} .small{font-size:13px}'''
(SITE/'style.css').write_text(CSS,encoding='utf-8')
def shell(title,body):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Useful free tools and templates for independent businesses."><title>{html.escape(title)} | ToolFoundry</title><link rel="stylesheet" href="/style.css"></head><body><header><div class="wrap"><a class="brand" href="/">TOOLFOUNDRY</a><span class="pill">Independent business tools</span></div></header><main class="wrap">{body}</main><footer><div class="wrap">© ToolFoundry · Practical tools, not financial or tax advice. <a href="/privacy.html">Privacy</a></div></footer></body></html>'''
# Products are real downloadable templates, not dummy buttons.
with (PRODUCTS/'small-business-cashflow.csv').open('w',newline='') as f:
 w=csv.writer(f);w.writerow(['Month','Opening balance','Sales receipts','Other income','Materials','Wages','Rent','Marketing','Other expenses','Closing balance'])
 for i in range(1,13):
  row=i+1;w.writerow([f'Month {i}', '0' if i==1 else f'=J{row-1}',0,0,0,0,0,0,0,f'=B{row}+C{row}+D{row}-SUM(E{row}:I{row})'])
with (PRODUCTS/'project-quote-template.csv').open('w',newline='') as f:
 w=csv.writer(f);w.writerow(['Project','Client','Quote reference','Date','Item','Quantity','Unit rate GBP','Line total GBP','VAT rate','VAT GBP','Total GBP'])
 for i in range(2,22):w.writerow(['','','','','',0,0,f'=F{i}*G{i}',0.2,f'=H{i}*I{i}',f'=H{i}+J{i}'])
(PRODUCTS/'README.txt').write_text('ToolFoundry templates. Open CSV in Excel, Google Sheets or LibreOffice. Enter your own values. Check formula compatibility and local tax rules. These are planning aids, not professional advice.\n',encoding='utf-8')
with zipfile.ZipFile(SITE/'business-template-pack.zip','w',zipfile.ZIP_DEFLATED) as z:
 for name in ['small-business-cashflow.csv','project-quote-template.csv','README.txt']:z.write(PRODUCTS/name,name)
calculator='''<section class="hero"><span class="tag">Free interactive tool</span><h1>Freelance rate calculator</h1><p class="muted">Estimate your minimum hourly rate. All calculations happen in your browser; we do not collect your inputs.</p></section><div class="card" style="max-width:650px"><label>Desired annual take-home income (£)<input id="income" type="number" min="0" value="40000"></label><label>Annual business expenses (£)<input id="expenses" type="number" min="0" value="6000"></label><label>Tax and contributions reserve (%)<input id="tax" type="number" min="0" max="95" value="25"></label><label>Billable hours per week<input id="hours" type="number" min="1" value="25"></label><label>Working weeks per year<input id="weeks" type="number" min="1" max="52" value="46"></label><p class="muted small">Assumes the reserve is a percentage of revenue after expenses. This is a rough planning estimate, not a tax calculation.</p><p>Estimated minimum hourly rate</p><strong class="result" id="result" aria-live="polite">—</strong></div><script>function calculate(){let v=id=>Number(document.getElementById(id).value);let net=v('income'),expenses=v('expenses'),tax=v('tax'),hours=v('hours'),weeks=v('weeks');let out=document.getElementById('result');if([net,expenses,tax,hours,weeks].some(x=>!Number.isFinite(x))||net<0||expenses<0||tax<0||tax>=100||hours<=0||weeks<=0||weeks>52){out.textContent='Check your inputs';return}let revenue=expenses+net/(1-tax/100);out.textContent=new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP'}).format(revenue/(hours*weeks))+' / hour'}document.querySelectorAll('input').forEach(x=>x.addEventListener('input',calculate));calculate();</script>'''
(SITE/'freelance-rate-calculator.html').write_text(shell('Freelance Rate Calculator',calculator),encoding='utf-8')
links={'freelance-rate-calculator':'/freelance-rate-calculator.html','small-business-cashflow':'/business-template-pack.zip','project-quote-template':'/business-template-pack.zip'}
cards=''.join(f'''<article class="card"><span class="tag">{p['category']} · {p['price']}</span><h3>{p['title']}</h3><p class="muted">{p['desc']}</p><a class="btn" href="{links[p['slug']]}">{'Open calculator' if p['kind']=='calculator' else 'Download free pack'}</a></article>''' for p in CATALOG)
landing=f'''<section class="hero"><span class="tag">Simple tools. Real utility.</span><h1>Less admin. Better decisions.</h1><p class="muted" style="max-width:630px">Free calculators and downloadable templates built for freelancers and small businesses. No account required.</p></section><h2>Available tools</h2><div class="grid">{cards}</div><section style="margin-top:50px"><h2>How it works</h2><p class="muted">Use the calculator instantly, or download the editable CSV templates. Products are provided as-is; always review figures before relying on them.</p></section>'''
(SITE/'index.html').write_text(shell('Free business tools',landing),encoding='utf-8')
(SITE/'privacy.html').write_text(shell('Privacy','<section class="hero"><h1>Privacy</h1><p>This starter website does not use analytics, cookies, accounts or a contact form. Calculator inputs are processed locally in your browser. If you later enable analytics, email capture or a payment provider, update this policy and your business details before publishing.</p></section>'),encoding='utf-8')
(SITE/'robots.txt').write_text('User-agent: *\nAllow: /\n',encoding='utf-8')
(SITE/'catalog.json').write_text(json.dumps(CATALOG,indent=2),encoding='utf-8')
print('Built',len(CATALOG),'products into',SITE)
